 * Parses a `process.argv`-style array for shell completion.
 *
 * The incoming array looks like `[node, /path/to/nx, <user tokens...>]`. The
 * first two entries (node runtime + nx binary path) are stripped, and a
 * leading `nx` script-name token (present in some shells' completion
 * invocations) is stripped as well.
 *
 * @returns An object with the remaining shell `tokens`, the `current` token
 * being completed (the last token), and the `previousToken` (the
 * second-to-last token, or `''` when only one token remains). Returns `null`
 * when no user-supplied tokens remain after stripping.
 */
export function parseCompletionArgs(
  argv: string[]
): { tokens: string[]; current: string; previousToken: string } | null {
  let tokens = argv.slice(2);

  if (tokens[0] === 'nx') {
    tokens = tokens.slice(1);
  }

  if (tokens.length === 0) {
    return null;
  }

  const current = tokens[tokens.length - 1];
  const previousToken = tokens.length > 1 ? tokens[tokens.length - 2] : '';

  return { tokens, current, previousToken };
}
