  // The last token is the partial string currently being completed; the path
  // and positional index are derived from the already-committed tokens.
  const committed = tokens.slice(0, -1);

  const pathTokens: string[] = [];
  for (const token of committed) {
    if (token.startsWith('--')) {
      break;
    }
    pathTokens.push(token);
  }

  let metadata: CompletionMetadata | null = null;
  let matchedLength = 0;
  for (let len = pathTokens.length; len >= 1; len--) {
    const path = pathTokens.slice(0, len).join(' ');
    if (registry.has(path)) {
      metadata = registry.get(path)!;
      matchedLength = len;
      break;
