const commandFlagConfigs: Record<string, CommandFlagConfig> = {
  'run-many': {
    projects: projectFlagHandler,
    targets: targetFlagHandler,
  },
  affected: {
    projects: projectFlagHandler,
    exclude: projectFlagHandler,
    targets: targetFlagHandler,
  },
  graph: {
    focus: projectFlagHandler,
    exclude: projectFlagHandler,
    targets: targetFlagHandler,
  },
  watch: {
    projects: projectFlagHandler,
  },
};

