function getAddPackageCompletions(current: string): string[] {
  try {
    const nxPackageJson = require(require.resolve('nx/package.json'));
    const packageGroup: Array<string | { package: string }> =
      nxPackageJson['nx-migrations']?.packageGroup ?? [];
    return packageGroup
      .map((entry) => (typeof entry === 'string' ? entry : entry.package))
      .filter((name) => name.startsWith('@nx/') && name.startsWith(current));
  } catch {
    return [];
  }
}
